export const getUsersPage = createServerFn({ method: 'GET' })
  .validator((input: { page: number; pageSize: number }) => input)
  .handler(async ({ data }) => {
    await new Promise((resolve) => setTimeout(resolve, 400))

    const start = data.page * data.pageSize
    return {
      rows: Users.slice(start, start + data.pageSize),
      pageCount: Math.ceil(Users.length / data.pageSize),
    }
  })

export const getUserPageWithFilter = createServerFn({ method: "GET" })
  .validator((input: { page: number; pageSize: number; role?: string; status?: string }) => input)
  .handler(async ({ data }) => {
    await new Promise((resolve => setTimeout(resolve, 400)))

    const filtered = Users.filter((u) => {
      if (data.role && u.role !== data.role) return false
      if (data.status && u.status !== data.status) return false
      return true
    })

    const start = data.page * data.pageSize
    return {
      rows: filtered.slice(start, start + data.pageSize),
      pageCount: Math.ceil(filtered.length / data.pageSize),
    }
  })

export const getUsersPageCombined = createServerFn({ method: 'GET' })
  .validator(
    (input: {
      page: number
      pageSize: number
      role?: string
      status?: string
      sortBy?: string
      sortDir?: 'asc' | 'desc'
    }) => input,
  )
  .handler(async ({ data }) => {
    await new Promise((resolve) => setTimeout(resolve, 400))

    // 1. Filter — same as getUserPageWithFilter, resolved server-side first.
    const filtered = Users.filter((u) => {
      if (data.role && u.role !== data.role) return false
      if (data.status && u.status !== data.status) return false
      return true
    })

    // 2. Sort — runs against the already-filtered set, never the full table.
    const sorted = data.sortBy
      ? [...filtered].sort((a, b) => {
          const key = data.sortBy as keyof User
          const aVal = a[key]
          const bVal = b[key]
          const dir = data.sortDir === 'desc' ? -1 : 1
          if (aVal < bVal) return -1 * dir
          if (aVal > bVal) return 1 * dir
          return 0
        })
      : filtered

    // 3. Paginate — the last step, so page counts reflect filtered+sorted rows.
    const start = data.page * data.pageSize
    return {
      rows: sorted.slice(start, start + data.pageSize),
      pageCount: Math.ceil(sorted.length / data.pageSize),
    }
  })

'use client'

import { flexRender, getCoreRowModel, useReactTable } from '@tanstack/react-table'
import type { ColumnDef, SortingState } from '@tanstack/react-table'
import { useRouterState } from '@tanstack/react-router'

import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '#/components/ui/table'
import { Button } from '#/components/ui/button'
import {
  ArrowDown,
  ArrowUp,
  ArrowUpDown,
  ChevronLeft,
  ChevronRight,
  ChevronsLeft,
  ChevronsRight,
} from 'lucide-react'
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '#/components/ui/select'
import { cn } from '#/lib/utils.ts'
import type { User } from './columns'
import { Route } from '#/routes/server-combined-table'

interface DataTableProps {
  columns: ColumnDef<User>[]
}

const PAGES_SIZE = [
  { label: '10', value: '10' },
  { label: '20', value: '20' },
  { label: '30', value: '30' },
  { label: '40', value: '40' },
  { label: '50', value: '50' },
]

export function DataTable({ columns }: DataTableProps) {
  const { page, pageSize, role, status, sortBy, sortDir } = Route.useSearch()
  const { rows, pageCount } = Route.useLoaderData()
  const navigate = Route.useNavigate()
  const isPending = useRouterState({ select: (s) => s.isLoading })

  // Sort state is derived from the URL, not local useState — the URL stays
  // the single source of truth, matching filtering and pagination.
  const sorting: SortingState = sortBy
    ? [{ id: sortBy, desc: sortDir === 'desc' }]
    : []

  const table = useReactTable({
    data: rows,
    columns,
    pageCount,
    manualPagination: true,
    manualSorting: true,
    manualFiltering: true,
    getCoreRowModel: getCoreRowModel(),
    state: {
      sorting,
      pagination: { pageIndex: page, pageSize },
    },
    onSortingChange: (updater) => {
      const next = typeof updater === 'function' ? updater(sorting) : updater
      const nextSort = next[0]
      navigate({
        search: (prev) => ({
          ...prev,
          sortBy: nextSort?.id ?? '',
          sortDir: nextSort?.desc ? 'desc' : 'asc',
          page: 0, // reset to page 0 — the result order changed
        }),
      })
    },
    onPaginationChange: (updater) => {
      const next =
        typeof updater === 'function'
          ? updater({ pageIndex: page, pageSize })
          : updater
      navigate({
        search: (prev) => ({
          ...prev,
          page: next.pageIndex,
          pageSize: next.pageSize,
        }),
      })
    },
  })

  return (
    <div>
      <div className="mb-4 flex flex-wrap gap-2">
        <Select
          value={role || 'all'}
          onValueChange={(val) =>
            navigate({
              search: (prev) => ({
                ...prev,
                role: val === 'all' ? '' : val,
                page: 0, // reset to page 0 — the result set size changed
              }),
            })
          }
        >
          <SelectTrigger className="w-32">
            <SelectValue placeholder="Role" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All roles</SelectItem>
            <SelectItem value="Admin">Admin</SelectItem>
            <SelectItem value="Editor">Editor</SelectItem>
            <SelectItem value="Viewer">Viewer</SelectItem>
          </SelectContent>
        </Select>
        <Select
          value={status || 'all'}
          onValueChange={(val) =>
            navigate({
              search: (prev) => ({
                ...prev,
                status: val === 'all' ? '' : val,
                page: 0,
              }),
            })
          }
        >
          <SelectTrigger className="w-32">
            <SelectValue placeholder="Status" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All statuses</SelectItem>
            <SelectItem value="Active">Active</SelectItem>
            <SelectItem value="Inactive">Inactive</SelectItem>
            <SelectItem value="Pending">Pending</SelectItem>
          </SelectContent>
        </Select>
      </div>

      <div
        className={cn(
          'overflow-hidden rounded-md border transition-opacity',
          isPending && 'opacity-50',
        )}
      >
        <Table>
          <TableHeader>
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow key={headerGroup.id}>
                {headerGroup.headers.map((header) => {
                  const canSort = header.column.getCanSort()
                  const sortHandler = header.column.getToggleSortingHandler()
                  return (
                    <TableHead
                      key={header.id}
                      onClick={sortHandler}
                      onKeyDown={(e) => {
                        if (canSort && (e.key === 'Enter' || e.key === ' ')) {
                          e.preventDefault()
                          sortHandler?.(e)
                        }
                      }}
                      tabIndex={canSort ? 0 : undefined}
                      role={canSort ? 'button' : undefined}
                      className={
                        canSort ? 'cursor-pointer select-none' : undefined
                      }
                    >
                      <div className="flex flex-row items-center gap-2">
                        {header.isPlaceholder
                          ? null
                          : flexRender(
                              header.column.columnDef.header,
                              header.getContext(),
                            )}
                        {canSort ? (
                          <span>
                            {header.column.getIsSorted() === 'asc' ? (
                              <ArrowUp className="h-3 w-3" />
                            ) : header.column.getIsSorted() === 'desc' ? (
                              <ArrowDown className="h-3 w-3" />
                            ) : (
                              <ArrowUpDown className="h-3 w-3 opacity-50" />
                            )}
                          </span>
                        ) : null}
                      </div>
                    </TableHead>
                  )
                })}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {table.getRowModel().rows.length ? (
              table.getRowModel().rows.map((row) => (
                <TableRow key={row.id}>
                  {row.getVisibleCells().map((cell) => (
                    <TableCell key={cell.id}>
                      {flexRender(
                        cell.column.columnDef.cell,
                        cell.getContext(),
                      )}
                    </TableCell>
                  ))}
                </TableRow>
              ))
            ) : (
              <TableRow>
                <TableCell
                  colSpan={columns.length}
                  className="h-24 text-center"
                >
                  No results.
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>

      <div className="mt-5 flex justify-end gap-1">
        <Button
          onClick={() => table.firstPage()}
          disabled={!table.getCanPreviousPage()}
          variant="outline"
        >
          <ChevronsLeft className="h-3 w-3" />
        </Button>
        <Button
          onClick={() => table.previousPage()}
          disabled={!table.getCanPreviousPage()}
          variant="outline"
        >
          <ChevronLeft className="h-3 w-3" />
        </Button>
        <Button
          onClick={() => table.nextPage()}
          disabled={!table.getCanNextPage()}
          variant="outline"
        >
          <ChevronRight className="h-3 w-3" />
        </Button>
        <Button
          onClick={() => table.lastPage()}
          disabled={!table.getCanNextPage()}
          variant="outline"
        >
          <ChevronsRight className="h-3 w-3" />
        </Button>
        <Select
          value={pageSize.toString()}
          onValueChange={(val) => table.setPageSize(Number(val))}
        >
          <SelectTrigger className="h-1/3">
            <SelectValue placeholder={PAGES_SIZE[0].label} />
          </SelectTrigger>
          <SelectContent>
            <SelectGroup>
              {PAGES_SIZE.map((item) => (
                <SelectItem key={item.value} value={item.value}>
                  {item.label}
                </SelectItem>
              ))}
            </SelectGroup>
          </SelectContent>
        </Select>
      </div>
    </div>
  )
}

import { columns } from './columns'
import { DataTable } from './data-table'

export function ServerCombinedDemo() {
  return <DataTable columns={columns} />
}

import { createFileRoute } from '@tanstack/react-router'
import { getUsersPageCombined } from '#/components/ssr/data'
import { ServerCombinedTablePage } from '#/components/ssr/combined-example/server-combined-table-page'

export const Route = createFileRoute('/server-combined-table')({
  head: () => ({
    meta: [
      { title: 'SSR Sort + Filter + Pagination — ShadTable' },
      {
        name: 'description',
        content:
          'Sorting, filtering, and pagination all resolved together on the server from one URL, instead of three separate demos — the way real dashboards actually work.',
      },
      {
        property: 'og:title',
        content: 'SSR Sort + Filter + Pagination — ShadTable',
      },
      {
        property: 'og:description',
        content:
          'A server-driven table combining sort, filter, and pagination in a single request, built on shadcn/ui and TanStack Table.',
      },
      {
        'script:ld+json': {
          '@context': 'https://schema.org',
          '@type': 'SoftwareSourceCode',
          name: 'SSR Sort + Filter + Pagination Table',
          description:
            'A server-driven table combining sort, filter, and pagination in a single request.',
          codeRepository: 'https://github.com/coros-hq/shadcn-table-library',
          programmingLanguage: 'TypeScript',
        },
      },
    ],
    links: [
      {
        rel: 'canonical',
        href: 'https://shad-table.dev/server-combined-table',
      },
    ],
  }),
  validateSearch: (search): {
    page: number
    pageSize: number
    role: string
    status: string
    sortBy: string
    sortDir: 'asc' | 'desc'
  } => ({
    page: Number(search.page ?? 0),
    pageSize: Number(search.pageSize ?? 10),
    role: (search.role as string) ?? '',
    status: (search.status as string) ?? '',
    sortBy: (search.sortBy as string) ?? '',
    sortDir: (search.sortDir as string) === 'desc' ? 'desc' : 'asc',
  }),
  loaderDeps: ({ search }) => search,
  loader: ({ deps }) => getUsersPageCombined({ data: deps }),
  component: ServerCombinedTablePage,
})
